<?php
$rows=$pdo->query("SELECT c.*,v.name vendor_name,DATEDIFF(c.end_date,CURDATE()) days_left FROM contracts c LEFT JOIN vendors v ON v.id=c.vendor_id WHERE c.status='Active' ORDER BY c.end_date")->fetchAll();
?><div class="page-head"><div><h1>Contract Monitoring</h1><p>Kontrol masa berlaku kontrak dan status kewajiban.</p></div><a href="index.php?page=reports" class="btn btn-outline-primary"><i class="bi bi-file-earmark-bar-graph me-1"></i> Monitoring Report</a></div><div class="card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Contract</th><th>Vendor</th><th>Start</th><th>End</th><th>Remaining</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):$days=(int)$r['days_left'];$cls=$days<=30?'danger':($days<=90?'warning':'success');?><tr><td><strong><?=de($r['contract_no'])?></strong><small class="d-block text-muted"><?=de($r['title'])?></small></td><td><?=de($r['vendor_name']?:'-')?></td><td><?=de($r['start_date'])?></td><td><?=de($r['end_date'])?></td><td><span class="monitor-badge <?=$cls?>"><?=max(0,$days)?> hari</span></td><td><span class="status-pill active">Active</span></td></tr><?php endforeach;?></tbody></table></div></div>
